+}
+
+main {
+  width: 100%;
+  max-width: 560px;
+}
+
+h1 {
+  font-size: 1.75rem;
+  margin: 0 0 0.5rem;
+  letter-spacing: -0.01em;
+}
+
+.intro {
+  color: var(--text-muted);
+  margin: 0 0 1.5rem;
+  font-size: 0.95rem;
+}
+
+.card {
+  background: var(--surface);
+  border: 1px solid var(--border);
+  border-radius: 12px;
+  padding: 1.75rem;
+}
+
+.visually-hidden {
+  position: absolute !important;
+  width: 1px; height: 1px;
+  padding: 0; margin: -1px;
+  overflow: hidden; clip: rect(0,0,0,0);
+  white-space: nowrap; border: 0;
+}
+
+.skip-link {
+  position: absolute;
+  left: -9999px;
+  top: auto;
+  background: var(--focus);
+  color: #000;
+  padding: 0.6rem 1rem;
+  border-radius: 6px;
+  font-weight: 600;
+  z-index: 100;
+}
+.skip-link:focus {
+  left: 1rem;
+  top: 1rem;
+  outline: 3px solid var(--focus);
+  outline-offset: 2px;
+}
+
+.form-field { margin-bottom: 1.5rem; }
+
+fieldset {
+  border: 0;
+  padding: 0;
+  margin: 0;
+}
+
+legend {
+  padding: 0;
+  font-size: 1.05rem;
+  font-weight: 600;
+  color: var(--text);
+  margin-bottom: 0.25rem;
+}
+
+legend span[aria-hidden="true"] {
+  color: var(--danger);
+  margin-left: 0.15rem;
+}
+
+.hint {
+  margin: 0 0 1rem;
+  color: var(--text-muted);
+  font-size: 0.9rem;
+}
+
+.radio-list {
+  display: flex;
+  flex-direction: column;
+  gap: 0.5rem;
+}
+
+.radio-item {
+  position: relative;
+  background: var(--surface-2);
+  border: 1px solid var(--border);
+  border-radius: 8px;
+  transition: border-color 120ms ease, background-color 120ms ease;
+}
+
+.radio-item:hover {
+  border-color: var(--border-strong);
+}
+
+.radio-item:has(input:checked) {
+  border-color: var(--accent);
+  background: #1a2333;
+}
+
+.radio-item:has(input:focus-visible) {
+  outline: 3px solid var(--focus);
+  outline-offset: 2px;
+}
+
+.radio-item input[type="radio"] {
+  /* Hide native control visually but keep accessible & focusable */
+  position: absolute;
+  opacity: 0;
+  inset: 0;
+  width: 100%;
+  height: 100%;
+  margin: 0;
+  cursor: pointer;
+}
+
+.radio-item label {
+  display: flex;
+  align-items: center;
+  gap: 0.75rem;
+  padding: 0.85rem 1rem;
+  cursor: pointer;
+  font-size: 1rem;
+  color: var(--text);
+  min-height: 44px;
+}
+
+.radio-item label::before {
+  content: "";
+  flex: 0 0 auto;
+  width: 20px;
+  height: 20px;
+  border-radius: 50%;
+  border: 2px solid var(--border-strong);
+  background: var(--bg);
+  display: inline-block;
+  transition: border-color 120ms ease, box-shadow 120ms ease;
+}
+
+.radio-item:has(input:checked) label::before {
+  border-color: var(--accent);
+  background: radial-gradient(circle, var(--accent) 0 5px, var(--bg) 6px 100%);
+  box-shadow: 0 0 0 1px var(--accent) inset;
+}
+
+.actions {
+  margin-top: 1.5rem;
+  display: flex;
+  gap: 0.75rem;
+}
+
+.btn-primary {
+  background: var(--accent-strong);
+  color: var(--accent-contrast);
+  border: 1px solid var(--accent-strong);
+  padding: 0.7rem 1.25rem;
+  font-size: 1rem;
+  font-weight: 600;
+  border-radius: 8px;
+  cursor: pointer;
+  min-height: 44px;
+  transition: background-color 120ms ease, border-color 120ms ease;
+}
+
+.btn-primary:hover { background: var(--accent); border-color: var(--accent); }
+
+.btn-primary:focus-visible {
+  outline: 3px solid var(--focus);
+  outline-offset: 2px;
+}
+
+.status {
+  margin: 1rem 0 0;
+  min-height: 1.25rem;
+  font-size: 0.95rem;
+  color: var(--success);
+}
+.status[data-kind="error"] { color: var(--danger); }
+
+@media (prefers-reduced-motion: reduce) {
+  * { transition: none !important; }
+}
+
+/* Forced colors / Windows High Contrast */
+@media (forced-colors: active) {
+  .radio-item { border-color: CanvasText; }
+  .radio-item:has(input:checked) { border-color: Highlight; }
+  .radio-item label::before { border-color: CanvasText; background: Canvas; }
+  .radio-item:has(input:checked) label::before {
+    background: Highlight;
+    border-color: Highlight;
+  }
+  .btn-primary {
+    background: ButtonFace; color: ButtonText; border-color: ButtonText;
+  }
+}
+
